from django.http import JsonResponse
from django.test import RequestFactory
from django.views.decorators.http import require_POST

print(JsonResponse({"tea": "hot"}, status=202).status_code)   # status= sets the number

@require_POST            # a decorator: other methods get 405
def ping(request):
    return JsonResponse({"reply": "pong"})

print(ping(RequestFactory().get("/ping/")).status_code)

def stock_check(count_text):
    try:
        count = int(count_text)
    except ValueError:
        log.exception("Stock check failed")
        return {"status": "error"}
    return {"status": "ok", "count": count}

print(stock_check("lots"))   # stock_check("12") gives {'status': 'ok', 'count': 12}
